// Active when forex.rate-provider=fixed (dev profile)
package com.bank.forex.service;

import lombok.extern.slf4j.Slf4j;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.Map;

@Service
@ConditionalOnProperty(name = "forex.rate-provider", havingValue = "fixed")
@Slf4j
public class FixedRateStrategy implements RateStrategy {

    private static final Map<String, BigDecimal> FIXED_RATES = Map.of(
        "INR_USD", new BigDecimal("0.012"),
        "INR_EUR", new BigDecimal("0.011"),
        "INR_GBP", new BigDecimal("0.0095"),
        "USD_INR", new BigDecimal("83.50"),
        "EUR_INR", new BigDecimal("91.20"),
        "GBP_INR", new BigDecimal("105.30")
    );

    @Override
    public BigDecimal getRate(String from, String to) {
        String key = from + "_" + to;
        BigDecimal rate = FIXED_RATES.getOrDefault(key, BigDecimal.ONE);
        log.debug("[FIXED] Rate {} → {}: {}", from, to, rate);
        return rate;
    }

    @Override
    public String getSourceName() { return "Fixed (Dev Mock)"; }
}
