package com.bank.forex.service;

import com.bank.forex.config.ForexConfig;
import com.bank.forex.dto.*;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.core.env.Environment;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Arrays;

@Service
@RequiredArgsConstructor
@Slf4j
public class ForexService {

    private final RateStrategy rateStrategy;  // injected by @Conditional — fixed or live
    private final ForexConfig config;
    private final Environment environment;    // to read active profiles

    public ConversionResponse convert(ConversionRequest request) {
        log.info("Converting Rs.{} from {} to {} using {}",
            request.amount(), request.fromCurrency(), request.toCurrency(),
            rateStrategy.getSourceName());

        // Validate against max amount from config
        if (config.maxConversionAmount() != null &&
            request.amount().compareTo(config.maxConversionAmount()) > 0) {
            throw new IllegalArgumentException("Amount exceeds max: " + config.maxConversionAmount());
        }

        BigDecimal rate = rateStrategy.getRate(request.fromCurrency(), request.toCurrency());
        BigDecimal converted = request.amount().multiply(rate).setScale(2, RoundingMode.HALF_UP);

        String activeProfile = String.join(",", environment.getActiveProfiles());

        return new ConversionResponse(
            request.fromCurrency(), request.toCurrency(),
            request.amount(), rate, converted,
            rateStrategy.getSourceName(), activeProfile);
    }
}
