package com.bank.forex.service;

import com.bank.forex.config.ForexConfig;
import com.bank.forex.dto.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.*;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.core.env.Environment;
import java.math.BigDecimal;
import java.time.Duration;
import java.util.List;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class ForexServiceTest {

    @Mock RateStrategy rateStrategy;
    @Mock Environment environment;

    @Test
    void shouldConvertUsingConfiguredStrategy() {
        ForexConfig config = new ForexConfig("INR", List.of("USD"),
            Duration.ofMinutes(5), "fixed", null, null, new BigDecimal("10000000"));

        ForexService service = new ForexService(rateStrategy, config, environment);

        when(rateStrategy.getRate("INR", "USD")).thenReturn(new BigDecimal("0.012"));
        when(rateStrategy.getSourceName()).thenReturn("Fixed (Dev)");
        when(environment.getActiveProfiles()).thenReturn(new String[]{"dev"});

        ConversionResponse response = service.convert(
            new ConversionRequest("INR", "USD", new BigDecimal("100000")));

        assertThat(response.convertedAmount()).isEqualByComparingTo("1200.00");
        assertThat(response.rateSource()).isEqualTo("Fixed (Dev)");
        assertThat(response.profile()).isEqualTo("dev");
    }
}
